function nav(id,opts={}){if(state.busy)return;state.history.push({route:state.route,form:{...state.form},tab:state.tab,purpose:state.purpose});state.route=id;state.query='';state.error='';state.scenario='normal';state.form={};Object.assign(state,opts);history.replaceState(null,'','#'+id);render();}
function back(){if(state.busy)return;const last=state.history.pop();if(last){Object.assign(state,last,{error:'',scenario:'normal',query:''});history.replaceState(null,'','#'+state.route);render();}else nav('home');}
function btn(text,to,kind='',attrs=''){return `<button class="button ${kind}" ${to?`data-go="${to}"`:''} ${attrs}>${esc(text)}</button>`;}
function action(text,name,kind='',attrs=''){return `<button class="button ${kind}" data-action="${name}" ${attrs}>${esc(text)}</button>`;}
function row(title,subtitle,to,value='',ico='next',attrs=''){const tag=to?'button':'div';return `<${tag} class="row" ${to?`data-go="${to}"`:''} ${attrs}><span class="row-copy"><strong>${esc(title)}</strong>${subtitle?`<small>${esc(subtitle)}</small>`:''}</span>${value?`<span class="row-value">${esc(value)}</span>`:''}${to?icon(ico):''}</${tag}>`;}
function field(label,name,value='',type='text',hint='',required=false,options=[]){let control;if(type==='select')control=`<select name="${name}" ${required?'required':''}>${options.map(o=>{const v=typeof o==='string'?o:o.value,t=typeof o==='string'?o:o.label;return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''} ${o.disabled?'disabled':''}>${esc(t)}</option>`;}).join('')}</select>`;else if(type==='textarea')control=`<textarea name="${name}" maxlength="200">${esc(value)}</textarea>`;else control=`<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='number'?'min="0" max="9999" step="1"':''} ${type==='password'?'autocomplete="new-password"':''}>`;return `<label class="form-field"><span>${esc(label)}${required?' *':''}</span>${control}${hint?`<span class="hint">${esc(hint)}</span>`:''}</label>`;}
const notice=t=>`<div class="notice">${t}</div>`;
const kv=(k,v,em=false)=>`<div class="key-value ${em?'emphasis':''}"><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`;
function search(placeholder){return `<div class="search">${icon('search')}<input aria-label="${placeholder}" id="search" placeholder="${placeholder}" value="${esc(state.query)}"></div>`;}
function chips(items,current,actionName){return `<div class="chips">${items.map(t=>`<button class="chip ${t===current?'active':''}" data-action="${actionName}" data-value="${t}">${t}</button>`).join('')}</div>`;}
function tabs(){return `<nav class="bottom-nav" aria-label="主导航">${[['home','home','首页'],['members','users','会员'],['workbench','grid','工作台'],['my','user','我的']].map(([id,i,t])=>`<button data-go="${id}" class="${state.route===id?'active':''}" ${state.route===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function footer(html){return `<div class="app-footer">${html}</div>`;}
function memberSummary(){const m=member();return `<div class="identity"><div class="avatar">${esc(m.name.slice(0,1))}</div><div><strong>${esc(m.name||m.nickName)}</strong><small>${esc(m.phone||'未填写手机号')} · ${esc(m.source)}</small></div></div>`;}
function recordRow(r){return row(r.name,`${r.type} · ${r.time.replace('T',' ').slice(5)}`,'record',r.type==='会员次卡'?`扣 ${r.times} 次`:'非次卡消费','next',`data-record-id="${r.id}"`);}
function totalRemain(m){return m.cards.reduce((n,c)=>n+c.remain,0);}
function usable(c){return c.status==='正常'&&c.remain>0&&(!c.expire||c.expire>='2026-10-20');}
function listState(){if(state.scenario==='loading')return `<div role="status" class="loading-skeleton"><p>正在加载，请稍候</p><div class="blank-block"></div><div class="blank-block"></div><div class="blank-block"></div></div>`;if(state.scenario==='error')return `<div class="empty">${icon('alert')}<strong>加载失败</strong><p>暂时无法获取数据，请重试。</p>${action('重新加载','retry','secondary')}</div>`;if(state.scenario==='empty')return `<div class="empty">${icon('empty')}<strong>暂无数据</strong><p>${state.route==='members'?'门店还没有会员，可以先建立档案。':'当前范围没有记录，可调整筛选后查看。'}</p>${state.route==='members'?btn('新增会员','member-form','secondary'):action('恢复演示数据','retry','secondary')}</div>`;return '';}
